import {connect} from './cdp.mjs'; import fs from 'node:fs'; import {execSync} from 'node:child_process';
const [E,LOG,KB]=process.argv.slice(2); const R={}; const c=await connect(); c.events.length=0;
const ask=async q=>{await c.click(`document.querySelector('#question-input')`); await c.type(q); await c.key('Enter');};
const nArt=`document.querySelectorAll('[role=log] article[aria-label^="Exchange"]').length`;
const idle=async()=>{await c.sleep(30);await c.waitFor(`!document.querySelector('article[aria-busy=true]')`);await c.sleep(250);};
R.before=await c.ev(nArt);
fs.copyFileSync(KB+'/qa-history.json',KB+'/../qa-good.json'); fs.writeFileSync(KB+'/qa-history.json','{not json');
await ask('How does retrieval work?'); await idle();
R.err=await c.ev(`(()=>{const e=document.querySelector('article[aria-label="Question that could not be answered"]');return {present:!!e,text:e?.innerText,exchanges:${nArt},input:document.querySelector('#question-input').value,header:document.querySelector('#conversation-heading').textContent}})()`);
await c.shot(E+'/13-error.png');
// second failure while still corrupt, different question
await ask('Second failing question'); await idle();
R.err2=await c.ev(`[...document.querySelectorAll('article[aria-label="Question that could not be answered"]')].map(a=>a.innerText.split('\\n')[1])`);
// Clear while file corrupt? skip. Restore and Retry
fs.copyFileSync(KB+'/../qa-good.json',KB+'/qa-history.json');
await c.click(`[...document.querySelectorAll('button')].find(b=>b.textContent==='Retry')`); await idle();
R.afterRetry=await c.ev(`({exchanges:${nArt},err:!!document.querySelector('article[aria-label="Question that could not be answered"]'),last:[...document.querySelectorAll('[role=log] article')].at(-1).innerText.split('\\n')[1]})`);
await c.shot(E+'/14-after-retry.png');
R.qaFailedInLog=fs.readFileSync(LOG,'utf8').split('\n').filter(l=>l.includes('Q&A failed')).length;
// stale citation: delete design-notes via API without refreshing list
const docs=await c.ev(`window.knowledgeBase.documents.list()`); const dn=docs.find(d=>d.title==='design-notes');
await c.ev(`window.knowledgeBase.documents.delete('${dn.id}')`);
c.events.length=0;
const citeSel=`[...document.querySelectorAll('[role=log] li li button')].find(b=>b.textContent.startsWith('design-notes'))`;
await c.click(citeSel); await c.sleep(500);
R.staleNoRefresh=await c.ev(`({detail:document.querySelector('section[aria-label="Selected document"] h2')?.textContent, citeText:${citeSel}.innerText, docsHeader:document.querySelector('h2').textContent})`);
await c.shot(E+'/15-stale-citation-before-refresh.png');
await c.click(`[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Refresh')`); await c.sleep(400);
const closeBtn=await c.ev(`!!document.querySelector('button[aria-label="Close document"]')`); if(closeBtn){await c.click(`document.querySelector('button[aria-label="Close document"]')`);await c.sleep(200);}
await c.click(citeSel); await c.sleep(500);
R.staleAfterRefresh=await c.ev(`({detail:document.querySelector('section[aria-label="Selected document"] h2')?.textContent??null, citeText:${citeSel}.innerText, docsHeader:document.querySelector('h2').textContent})`);
await c.shot(E+'/16-stale-citation-after-refresh.png');
R.events=c.events;
R.onScreen=await c.ev(`[...document.querySelectorAll('[role=log] article[aria-label^="Exchange"]')].map(a=>({q:a.querySelector('div div:nth-child(2)').textContent, t:a.querySelector('time').getAttribute('datetime'), c:[...a.querySelectorAll('li button > span:first-child')].map(s=>s.textContent)}))`);
fs.writeFileSync(E+'/p3.json',JSON.stringify(R,null,2)); console.log(JSON.stringify({...R,onScreen:R.onScreen.length},null,2)); c.close();

